import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"设计与实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"},{"text":"GenSimplifiedKey回调实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/gen_simplified_key"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/gen_simplified_key.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/gen_simplified_key.md","outlineHeaders":[{"level":2,"title":"使用场景和职责边界","slug":"使用场景和职责边界","link":"#使用场景和职责边界"},{"level":2,"title":"函数签名","slug":"函数签名","link":"#函数签名"},{"level":2,"title":"编写回调","slug":"编写回调","link":"#编写回调"},{"level":2,"title":"注册回调","slug":"注册回调","link":"#注册回调"},{"level":2,"title":"编写要求","slug":"编写要求","link":"#编写要求"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787886219000}'),e={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/gen_simplified_key.md"};function c(t,s,i,d,o,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>GenSimplifiedKey回调实现</h1><p>本文介绍如何编写并注册<code>GenSimplifiedKey</code>回调。该回调用于预编译多份核函数（Kernel）binary的场景：算子开发者根据本次调用的输入、输出和属性生成一个自定义simplified key片段，运行时框架使用该片段查找对应的binary。</p><p>本文只说明回调如何生成Key。如何在编译时提供每个Key对应的binary，请参见<a href="../compilation_and_deployment/simplified_key_json_configuration.html">simplified key二进制配置JSON</a>；运行时如何调用回调并选择binary，请参见<a href="../invocation/simplified_key_runtime_flow.html">基于simplified key的运行时选择流程</a>。</p><h2 id="使用场景和职责边界">使用场景和职责边界<a class="header-anchor" href="#使用场景和职责边界">​</a></h2><p>普通算子由运行时根据常规支持信息匹配binary。对于一个算子需要按自定义维度选择多份预编译binary的场景，例如按输入dtype、format、shape分档或属性组合选择，可以使用<code>GenSimplifiedKey</code>。</p><p><code>GenSimplifiedKey</code>的职责边界如下：</p><p><strong>表1</strong> simplified key各参与方职责</p><table><thead><tr><th>参与方</th><th>职责</th></tr></thead><tbody><tr><td>算子开发者</td><td>枚举需要编译的组合，在JSON中为每份binary声明<code>simplified_key</code>；编写回调，从本次调用信息生成相同的Key片段。</td></tr><tr><td>编译工具链</td><td>按JSON拆分并编译每个组合，将完整simplified key和binary路径写入产物配置。</td></tr><tr><td>运行时框架</td><td>调用回调生成片段，组装完整simplified key，查找并加载匹配的binary。</td></tr></tbody></table><p>回调不加载binary，也不决定TilingKey或核函数（Kernel）入口；这些工作仍由运行时框架和已注册的<code>TilingFunc</code>完成。</p><h2 id="函数签名">函数签名<a class="header-anchor" href="#函数签名">​</a></h2><p>注册接口接受的函数类型为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="n">GenSimplifiedKeyKernelFunc</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">UINT32</span><span class="w"> </span><span class="p">(</span><span class="o">*</span><span class="p">)(</span><span class="n">gert</span><span class="o">::</span><span class="n">TilingContext</span><span class="w"> </span><span class="o">*</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">char_t</span><span class="w"> </span><span class="o">*</span><span class="p">);</span>
</code></pre></div><p>实际函数通常声明为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">static</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">graphStatus</span><span class="w"> </span><span class="nf">GenSimplifiedKeyFunc</span><span class="p">(</span>
<span class="w">    </span><span class="n">gert</span><span class="o">::</span><span class="n">TilingContext</span><span class="o">*</span><span class="w"> </span><span class="n">context</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">char_t</span><span class="o">*</span><span class="w"> </span><span class="n">simplifiedKey</span><span class="p">);</span>
</code></pre></div><p>参数说明如下：</p><p><strong>表2</strong> GenSimplifiedKey回调参数说明</p><table><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>context</code></td><td>本次调用的Host侧上下文。可读取输入和输出描述、shape、属性等选择维度。</td></tr><tr><td><code>simplifiedKey</code></td><td>由运行时提供的输出缓冲区。回调将自定义Key片段写入该缓冲区。</td></tr><tr><td>返回值</td><td>成功返回<code>ge::GRAPH_SUCCESS</code>，无法生成有效片段时返回失败码。</td></tr></tbody></table><p>自定义Key片段经UTF-8编码后的长度必须小于256字节，不能包含算子类型、<code>d=</code>或<code>p=</code>等完整Key前缀。完整simplified key经UTF-8编码后的长度必须小于1024字节。</p><h2 id="编写回调">编写回调<a class="header-anchor" href="#编写回调">​</a></h2><p>以下示例来自<code>AddCustomTemplate</code>。该样例支持FP16和FP32两种组合，两个输入和一个输出使用相同dtype，因此只读取输入<code>x</code>的dtype就足以区分binary。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">static</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">graphStatus</span><span class="w"> </span><span class="nf">GenSimplifiedKeyFunc</span><span class="p">(</span>
<span class="w">    </span><span class="n">gert</span><span class="o">::</span><span class="n">TilingContext</span><span class="o">*</span><span class="w"> </span><span class="n">context</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">char_t</span><span class="o">*</span><span class="w"> </span><span class="n">simplifiedKey</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">size_t</span><span class="w"> </span><span class="n">CUSTOM_SIMPLIFIED_KEY_MAX_LEN</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256U</span><span class="p">;</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">context</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="nb">nullptr</span><span class="w"> </span><span class="o">||</span><span class="w"> </span><span class="n">simplifiedKey</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="nb">nullptr</span><span class="w"> </span><span class="o">||</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetInputDesc</span><span class="p">(</span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_FAILED</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">key</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="k">switch</span><span class="w"> </span><span class="p">(</span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetInputDesc</span><span class="p">(</span><span class="mi">0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">GetDataType</span><span class="p">())</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">case</span><span class="w"> </span><span class="no">ge</span><span class="o">::</span><span class="no">DT_FLOAT16</span><span class="p">:</span>
<span class="w">            </span><span class="n">key</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="s">&quot;custom_fp16&quot;</span><span class="p">;</span>
<span class="w">            </span><span class="k">break</span><span class="p">;</span>
<span class="w">        </span><span class="k">case</span><span class="w"> </span><span class="no">ge</span><span class="o">::</span><span class="no">DT_FLOAT</span><span class="p">:</span>
<span class="w">            </span><span class="n">key</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="s">&quot;custom_fp32&quot;</span><span class="p">;</span>
<span class="w">            </span><span class="k">break</span><span class="p">;</span>
<span class="w">        </span><span class="k">default</span><span class="o">:</span>
<span class="w">            </span><span class="k">return</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_FAILED</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">strcpy_s</span><span class="p">(</span><span class="n">simplifiedKey</span><span class="p">,</span><span class="w"> </span><span class="n">CUSTOM_SIMPLIFIED_KEY_MAX_LEN</span><span class="p">,</span><span class="w"> </span><span class="n">key</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">EOK</span>
<span class="w">        </span><span class="o">?</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_SUCCESS</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_FAILED</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div><p>该函数和JSON的对应关系如下：</p><p><strong>表3</strong> AddCustomTemplate回调与binary对应关系</p><table><thead><tr><th>运行时输入<code>x</code>的dtype</th><th>回调输出片段</th><th>JSON中的<code>simplified_key</code></th><th>选择的binary</th></tr></thead><tbody><tr><td><code>ge::DT_FLOAT16</code></td><td><code>custom_fp16</code></td><td><code>custom_fp16</code></td><td><code>AddCustomTemplate_FP16.o</code></td></tr><tr><td><code>ge::DT_FLOAT</code></td><td><code>custom_fp32</code></td><td><code>custom_fp32</code></td><td><code>AddCustomTemplate_FP32.o</code></td></tr></tbody></table><p>对于多输入、多输出或带属性的算子，凡是会改变binary选择结果的维度都必须同时出现在两端：JSON必须枚举组合，回调必须读取相应的<code>context</code>信息并生成唯一片段。例如binary同时依赖两个输入dtype时，应分别读取<code>context-&gt;GetInputDesc(0)</code>和<code>context-&gt;GetInputDesc(1)</code>；不能只读取第一个输入后假设其余输入相同。</p><h2 id="注册回调">注册回调<a class="header-anchor" href="#注册回调">​</a></h2><p>在算子原型的<code>OpDef</code>构造函数中注册回调，通常与Tiling函数一起配置：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">()</span>
<span class="w">    </span><span class="p">.</span><span class="n">SetTiling</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingFunc</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">SetGenSimplifiedKey</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">GenSimplifiedKeyFunc</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">AddConfig</span><span class="p">(</span><span class="s">&quot;ascendxxx&quot;</span><span class="p">);</span>
</code></pre></div><p><code>OP_ADD</code>注册算子原型时，会将该函数写入算子实现注册信息。运行时加载Host侧算子实现后，才能在调用过程中取得并调用此回调。</p><h2 id="编写要求">编写要求<a class="header-anchor" href="#编写要求">​</a></h2><ul><li>Key片段应只由会影响binary选择的稳定信息组成。不要使用内存地址、随机数、时间戳或会在同一输入条件下变化的内容。</li><li>同一调用条件必须始终生成相同片段；不同binary组合必须生成不同片段。</li><li>回调返回的片段必须与JSON中的<code>simplified_key</code>逐字节一致，包括大小写。</li><li>先检查<code>context</code>、输出缓冲区以及会访问的输入、输出描述是否为空；无法覆盖的组合返回失败码，不要写入不确定的默认Key。</li><li>回调应只完成轻量的描述信息读取和字符串写入，不应执行文件I/O、动态编译、复杂计算或设备侧操作。</li></ul><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./operator_prototype_definition.html">算子原型定义</a>：了解<code>SetGenSimplifiedKey</code>所在的原型注册位置。</li><li><a href="../compilation_and_deployment/simplified_key_json_configuration.html">simplified key二进制配置JSON</a>：了解JSON与编译产物的对应关系。</li><li><a href="../invocation/simplified_key_runtime_flow.html">基于simplified key的运行时选择流程</a>：了解运行时如何使用回调结果选择binary。</li></ul></article></div>`,1)])])}const m=a(e,[["render",c]]);export{g as __pageData,m as default};
